package com.bank.batchid.service;

import java.util.logging.Logger;

// Counts all contiguous palindromic substrings of the identifier.
public class BatchIdService {
    private static final Logger log = Logger.getLogger(BatchIdService.class.getName());

    public int symmetryScore(String identifier) {
        int n = identifier.length();
        boolean[][] dp = new boolean[n][n];         // dp[i][j] palindrome flag
        int count = 0;                              // running palindrome total
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = true;                        // single char palindrome
            count++;
            for (int j = i + 1; j < n; j++) {
                boolean endsMatch = identifier.charAt(i) == identifier.charAt(j);
                boolean innerOk = j - i < 2 || dp[i + 1][j - 1];
                if (endsMatch && innerOk) {
                    dp[i][j] = true;                // this range is a palindrome
                    count++;                        // count it
                }
            }
        }
        final int r = count;
        log.info(() -> "Symmetry score of " + identifier + " = " + r);
        return count;
    }
}
